<?php
namespace App\Http\Controllers\Admin\Academics;
use App\Models\Academics\DomainModule;use Illuminate\Http\Request;use Illuminate\View\View;
class DomainModuleController extends BaseAcademicsController{public function index(Request $r):View{$records=DomainModule::when($r->filled('search'),fn($q)=>$q->where('name','like','%'.$r->string('search').'%')->orWhere('urdu','like','%'.$r->string('search').'%'))->orderBy('id')->paginate(20)->withQueryString();$module=$r->integer('edit')?DomainModule::findOrFail($r->integer('edit')):null;return view('admin.academics.curriculum.domain-modules',compact('records','module'));}public function store(Request $r){$d=$r->validate(['eng_name'=>'required|array|min:1','eng_name.*'=>'required|string|max:100','urdu_name'=>'nullable|array','urdu_name.*'=>'nullable|string|max:100']);foreach($d['eng_name'] as $i=>$n)DomainModule::create(['name'=>$n,'urdu'=>$d['urdu_name'][$i]??'']);return back()->with('success','Modules added successfully.');}public function update(Request $r,DomainModule $domainModule){$d=$r->validate(['eng_name.0'=>'required|string|max:100','urdu_name.0'=>'nullable|string|max:100']);$domainModule->update(['name'=>$d['eng_name'][0],'urdu'=>$d['urdu_name'][0]??'']);return back()->with('success','Module updated successfully.');}public function destroy(DomainModule $domainModule){$domainModule->delete();return back()->with('success','Module deleted successfully.');}}
